export default {
  name: 'Report',
  components: {
    OrderBar: OrderBar,
    RoomPie: RoomPie
  },
  data: function data() {
    return {
      paramsInfo: {
        inspectionMonth: "2024-12",
        //巡视月份
        companyId: 1,
        //公司ID
        companyName: "XX公司",
        //公司名称
        deptName: 'XX信息运检班',
        //部门名称
        objectId: 1,
        //对象ID
        objectName: "XX机房",
        //机房名称
        type: 1 //类型 1机房 2设备
      },
      reportData: {
        startDate: "2024年12月1日",
        //开始时间
        finishDate: "2024年12月31日",
        //结束时间
        inspectCount: 3,
        //巡视总数
        planCount: 2,
        //涉及巡视计划总数
        personNum: 2,
        //涉及巡视人员数量
        abnormalNum: 3,
        //异常总数
        solvedNum: 2,
        //已解决异常数量
        unsolvedNum: 1,
        //未解决异常数量
        planList: [
        //巡视计划列表
        {
          no: "XSJH20241216000001",
          //计划编号
          period: "周计划巡视",
          //计划类别
          times: "15:00:00-16:00:00\n17:00:00-18:00:00",
          //巡视时间段
          index: 1,
          workerName: "刘丽娟、张三" //巡视人
        }, {
          no: "XSJH20241216000002",
          period: "月计划巡视",
          times: "09:00:00-11:30:00",
          index: 2,
          workerName: "刘丽娟"
        }],
        abnormalList: [
        //异常明细列表
        {
          code: "XSGD20241216000001",
          feedbackContent: "发现缺陷1处",
          feedbackPerson: "刘丽娟",
          configDetailName: "电脑巡视",
          index: 1
        }],
        personChartData: [
        //巡视人工单统计
        {
          personName: "李飞",
          orderNum: 1
        }, {
          personName: "刘丽娟",
          orderNum: 1
        }, {
          personName: "张三",
          orderNum: 1
        }],
        planOrderChartData: [
        //机房巡视工单饼图数据
        {
          name: "计划工单",
          value: 3
        }, {
          name: "临时工单",
          value: 0
        }]
      }
    };
  },
  created: function created() {
    this.paramsInfo = this.$route.query;
    this.getViewData();
  },
  methods: {
    handleDownload: function handleDownload() {
      var _this2 = this;
      var _this = this;
      //下载报告
      _this.$message.success('开始下载报告,请稍等...');
      createReportFile(_this.paramsInfo).then(function (res) {
        if (res.success && res.data) {
          _this.$message.success('报告创建成功,正在下载...');
          _this.exportFile(res.data);
        } else {
          _this.$message.error('报告创建失败');
        }
      }).catch(function (err) {
        console.log(err);
        _this2.$message.error('下载报告失败');
      });
    },
    exportFile: function exportFile(fileName) {
      var _this3 = this;
      var paramsInfo = this.paramsInfo;
      var reportData = this.reportData;
      var newFileName = paramsInfo.companyName + paramsInfo.objectName + '巡视报告(' + reportData.startDate + '至' + reportData.finishDate + ')';
      exportReportFile(fileName).then(function (res) {
        downloadFile(res, newFileName, 'docx');
      }).catch(function (err) {
        console.log(err);
        _this3.$message.error('报告导出失败');
      });
    },
    getViewData: function getViewData() {
      var _this = this;
      _this.reportData = {};
      getReportData(this.paramsInfo).then(function (res) {
        if (res.success) {
          _this.reportData = res.data;
        } else {
          _this.$message.warning(res.msg);
        }
      }).catch(function (err) {
        console.log(err);
        _this.$message.error('获取报告数据失败');
      });
    }
  }
};
